// Pattern: the app calls YOUR endpoint as the signed-in user.
@Serializable data class DescribeRequest(val photoPath: String, val question: String)
@Serializable data class DescribeResponse(val answer: String, val remainingToday: Int)

interface AiApi {
    @POST("ai/describe-photo")
    suspend fun describe(@Body body: DescribeRequest): DescribeResponse
}

// The client is authenticated by an interceptor that adds the user token (see networking).
val ai: AiApi = Retrofit.Builder()
    .baseUrl("https://api.example.com/")
    .client(authenticatedClient)
    .addConverterFactory(json.asConverterFactory("application/json".toMediaType()))
    .build().create()

// Server-side sketch (Kotlin/Ktor): limits before the expensive call.
suspend fun ApplicationCall.handleDescribe(deps: Deps) {
    val uid = verifiedUid() ?: return respond(HttpStatusCode.Unauthorized)
    if (!deps.rateLimiter.allow(uid, perMinute = 10)) return respond(HttpStatusCode.TooManyRequests, Retry(after = 60))
    val plan = deps.plans.of(uid)
    if (deps.quota.usedToday(uid, "describe") >= plan.dailyDescribeLimit) {
        return respond(HttpStatusCode.TooManyRequests, QuotaReached(resetsAt = tomorrowUtc()))
    }
    val req = receive<DescribeRequest>()
    require(req.question.length <= 500) { "Question too long" }
    val result = withTimeout(30.seconds) {
        deps.llm.describe(image = deps.storage.read(uid, req.photoPath), question = req.question, maxOutputTokens = 400)
    }
    deps.usage.record(uid, feature = "describe", input = result.inputTokens, output = result.outputTokens, costMicros = result.costMicros)
    respond(DescribeResponse(result.text, remainingToday = plan.dailyDescribeLimit - deps.quota.usedToday(uid, "describe")))
}

private val streamingClient = baseClient.newBuilder()
    .readTimeout(0, TimeUnit.SECONDS)          // no idle timeout between tokens
    .callTimeout(2, TimeUnit.MINUTES)          // but cap the whole answer
    .build()

fun streamChat(messages: List<ChatTurn>): Flow<String> = callbackFlow {
    val request = Request.Builder()
        .url("https://api.example.com/ai/chat/stream")
        .post(Json.encodeToString(ChatRequest(messages)).toRequestBody("application/json".toMediaType()))
        .build()
    val source = EventSources.createFactory(streamingClient).newEventSource(request, object : EventSourceListener() {
        override fun onEvent(es: EventSource, id: String?, type: String?, data: String) {
            if (data == "[DONE]") close() else trySend(Json.decodeFromString<Delta>(data).text)
        }
        override fun onFailure(es: EventSource, t: Throwable?, response: Response?) {
            close(t ?: IOException("Stream failed: ${response?.code}"))
        }
        override fun onClosed(es: EventSource) { close() }
    })
    awaitClose { source.cancel() }
}

// Emit buffered chunks at most every `period`.
fun Flow<String>.chunked(period: Duration): Flow<List<String>> = channelFlow {
    val buffer = mutableListOf<String>()
    val mutex = Mutex()
    val ticker = launch {
        while (isActive) {
            delay(period)
            mutex.withLock { if (buffer.isNotEmpty()) { send(buffer.toList()); buffer.clear() } }
        }
    }
    collect { mutex.withLock { buffer += it } }
    ticker.cancel()
    mutex.withLock { if (buffer.isNotEmpty()) send(buffer.toList()) }
}

@Composable
fun ChatList(messages: List<MessageUi>) {
    val listState = rememberLazyListState()
    val atBottom by remember { derivedStateOf { !listState.canScrollForward } }
    LaunchedEffect(messages.lastOrNull()?.text?.length) {
        if (atBottom && messages.isNotEmpty()) listState.scrollToItem(messages.lastIndex)
    }
    LazyColumn(state = listState) {
        items(messages, key = { it.id }) { MessageBubble(it) }
    }
}

@Dao
interface MessageDao {
    @Query("SELECT * FROM messages WHERE chatId = :chatId ORDER BY createdAt")
    fun observe(chatId: String): Flow<List<MessageEntity>>

    @Insert suspend fun insert(m: MessageEntity)

    @Query("UPDATE messages SET content = content || :delta WHERE id = :id")
    suspend fun appendContent(id: String, delta: String)

    @Query("UPDATE messages SET state = :state WHERE id = :id")
    suspend fun setState(id: String, state: MessageState)

    @Query("SELECT * FROM messages WHERE chatId = :chatId AND state = 'DONE' ORDER BY createdAt DESC LIMIT :limit")
    suspend fun lastTurnsDesc(chatId: String, limit: Int): List<MessageEntity>
}

@Composable
fun MessageBubble(m: MessageUi, onRetry: () -> Unit, onStop: () -> Unit) {
    when (m.state) {
        MessageState.STREAMING -> StreamingBubble(m.text, onStop)
        MessageState.FAILED -> FailedBubble(m.text, onRetry)               // keep partial text
        MessageState.STOPPED -> StoppedBubble(m.text)
        else -> DoneBubble(m.text)
    }
}

data class ContextWindow(val summary: String?, val recent: List<ChatTurn>)

suspend fun buildContext(chat: ConversationEntity, dao: MessageDao, keep: Int = 8): ContextWindow {
    val recent = dao.lastTurnsDesc(chat.id, keep).reversed().map { ChatTurn(it.role, it.content) }
    return ContextWindow(summary = chat.summary, recent = recent)     // summary refreshed by the backend
}

