@Serializable
data class VisionRequest(val question: String, val imageBase64: String, val mimeType: String = "image/jpeg")

class VisionRepository(private val context: Context, private val api: AiApi) {
    suspend fun ask(uri: Uri, question: String): String {
        val bytes = prepareImage(context, uri, maxSide = 1_280)          // ~150-300 KB, EXIF removed
        require(bytes.size < 1_500_000) { "Image still too large" }
        val b64 = Base64.encodeToString(bytes, Base64.NO_WRAP)
        return api.vision(VisionRequest(question.take(500), b64)).answer
    }
}

