class VoiceInput(private val context: Context) {
    fun listen(language: String = Locale.getDefault().toLanguageTag()): Flow<VoiceEvent> = callbackFlow {
        val recognizer = if (Build.VERSION.SDK_INT >= 33 && SpeechRecognizer.isOnDeviceRecognitionAvailable(context))
            SpeechRecognizer.createOnDeviceSpeechRecognizer(context)
        else SpeechRecognizer.createSpeechRecognizer(context)
        recognizer.setRecognitionListener(object : RecognitionListener {
            override fun onReadyForSpeech(p: Bundle?) { trySend(VoiceEvent.Listening) }
            override fun onPartialResults(b: Bundle) {
                b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)?.firstOrNull()?.let { trySend(VoiceEvent.Partial(it)) }
            }
            override fun onResults(b: Bundle) {
                trySend(VoiceEvent.Final(b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)?.firstOrNull().orEmpty()))
                close()
            }
            override fun onError(error: Int) { close(VoiceError(error)) }
            override fun onBeginningOfSpeech() = Unit; override fun onRmsChanged(v: Float) = Unit
            override fun onBufferReceived(b: ByteArray?) = Unit; override fun onEndOfSpeech() = Unit
            override fun onEvent(t: Int, b: Bundle?) = Unit
        })
        recognizer.startListening(Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, language)
            putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS, true)
        })
        awaitClose { recognizer.destroy() }
    }
}

// Pattern for any on-device feature: check, prepare, run, fall back.
sealed interface Availability { data object Ready : Availability; data object Downloadable : Availability; data object Unavailable : Availability }

interface OnDeviceFeature<I, O> {
    suspend fun availability(): Availability
    suspend fun download(onProgress: (Long) -> Unit)
    suspend fun run(input: I): O
}

class SmartSummary(
    private val onDevice: OnDeviceFeature<String, String>,
    private val cloud: suspend (String) -> String,
    private val userAllowsCloud: () -> Boolean,
) {
    suspend fun summarise(text: String, onProgress: (Long) -> Unit = {}): String? = when (onDevice.availability()) {
        Availability.Ready -> onDevice.run(text)
        Availability.Downloadable -> { onDevice.download(onProgress); onDevice.run(text) }
        Availability.Unavailable -> if (userAllowsCloud()) cloud(text) else null   // hide the button if null
    }
}

class ProductClassifier(context: Context, modelFile: File) : Closeable {
    private val classifier = ImageClassifier.createFromOptions(
        context,
        ImageClassifier.ImageClassifierOptions.builder()
            .setBaseOptions(BaseOptions.builder().setModelAssetPath(modelFile.absolutePath).build())
            .setMaxResults(3)
            .setScoreThreshold(0.4f)
            .build(),
    )

    suspend fun classify(bitmap: Bitmap): List<Pair<String, Float>> = withContext(Dispatchers.Default) {
        val result = classifier.classify(BitmapImageBuilder(bitmap).build())
        result.classificationResult().classifications().first().categories().map { it.categoryName() to it.score() }
    }

    override fun close() = classifier.close()
}

// Download the model once, on Wi-Fi, and verify it before use.
suspend fun ensureModel(context: Context, url: String, sha256: String): File = withContext(Dispatchers.IO) {
    val file = File(context.filesDir, "models/products_v3.tflite")
    if (file.exists() && file.sha256() == sha256) return@withContext file
    file.parentFile?.mkdirs()
    download(url, file)                                   // via WorkManager in a real app
    check(file.sha256() == sha256) { "Model corrupted" }
    file
}

